    const bool unordered = ma > infinity || mb > infinity;
    if (op == 12) return !unordered;
    if (op == 13) return unordered;
    if (unordered) return op >= 6 && op < 12;
    const bool equal = a == b || (ma == 0 && mb == 0);
    const bool sa = (a & sign) != 0, sb = (b & sign) != 0;
    const bool less = !equal && (sa != sb ? sa : (sa ? ma > mb : ma < mb));
