// UE8M0: value 2^(code - 127); code 255 is NaN. rz rounds the exponent down,
// rp up; .satfinite clamps to codes [0, 254].
static inline uint32_t gx_f64_to_ue8m0(double x, bool round_up) {
    if (x != x) return 0xffu;
    if (x <= 0) return 0u;
    if (__builtin_isinf(x)) return 254u;
    int e; double m = __builtin_frexp(x, &e);   // x = m * 2^e, m in [0.5, 1)
    int k = (m == 0.5) ? e - 1 : (round_up ? e : e - 1);
    int code = k + 127;
    return (uint32_t)(code < 0 ? 0 : code > 254 ? 254 : code);
}
