// Exact plain add.f16/add.f16x2 policy: binary16 RN-even, subnormals kept,
// overflow to infinity, and canonical qNaN for PTX's unspecified NaN payload.
static inline uint64_t gx_f16_finite_units(uint16_t x) {
    uint32_t e = (x >> 10) & 31u, f = x & 1023u;
    return e == 0 ? f : ((uint64_t)(1024u + f) << (e - 1));
}
static inline uint16_t gx_f16_add_rn_bits(uint16_t x, uint16_t y) {
    uint32_t ex = (x >> 10) & 31u, ey = (y >> 10) & 31u;
    uint32_t fx = x & 1023u, fy = y & 1023u;
    if ((ex == 31u && fx != 0) || (ey == 31u && fy != 0)) return 0x7e00u;
    if (ex == 31u) {
        if (ey == 31u && ((x ^ y) & 0x8000u)) return 0x7e00u;
        return (uint16_t)((x & 0x8000u) | 0x7c00u);
    }
    if (ey == 31u) return (uint16_t)((y & 0x8000u) | 0x7c00u);
    int64_t a = (int64_t)gx_f16_finite_units(x);
    int64_t b = (int64_t)gx_f16_finite_units(y);
    if (x & 0x8000u) a = -a;
    if (y & 0x8000u) b = -b;
    int64_t total = a + b;
    if (total == 0) return (uint16_t)(((x & 0x7fffu) == 0 &&
        (y & 0x7fffu) == 0 && (x & y & 0x8000u)) ? 0x8000u : 0u);
    uint16_t sign = total < 0 ? 0x8000u : 0u;
    uint64_t mag = total < 0 ? (uint64_t)(-total) : (uint64_t)total;
    if (mag < 1024u) return (uint16_t)(sign | mag);
    uint32_t top = 63u - (uint32_t)__builtin_clzll(mag);
    uint32_t shift = top - 10u;
    uint64_t scale = 1ull << shift;
    uint64_t q = mag / scale, rem = mag % scale, half = scale / 2u;
    if (shift != 0 && (rem > half || (rem == half && (q & 1u)))) ++q;
    if (q == 2048u) { q = 1024u; ++top; }
    uint32_t e = top - 9u;
    if (e >= 31u) return (uint16_t)(sign | 0x7c00u);
    return (uint16_t)(sign | (e << 10) | (uint16_t)(q - 1024u));
}
